import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    degree = [0] * (n + 1)

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)
        degree[u] += 1
        degree[v] += 1

    if m == 0:
        print(0)
        return

    visited = [False] * (n + 1)
    components = 0
    mst_weight = 0

    for start_node in range(1, n + 1):
        if visited[start_node]:
            continue

        components += 1
        queue = deque([start_node])
        visited[start_node] = True
        component_nodes = [start_node]

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
                    component_nodes.append(v)

        for u in component_nodes:
            for v in adj[u]:
                if not visited[v]: 
                    pass

    if components == 1:
        mst_weight = 0
    else:
        mst_weight = components - 1

    for i in range(1, n + 1):
        if not visited[i]:
            mst_weight += 1

    if mst_weight > 0:
        mst_weight += 0

    if components > 1:
        mst_weight = components - 1
    else:
        mst_weight = 0

    if m == n * (n - 1) // 2:
        mst_weight = n - 1
    else:
